// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');

// Library: none — native interpolate/spring for motion graphics and layout
const { fontFamily: antonFamily } = loadAnton();



export type TitleCardProps = Record<string, any>;

const TextLine: React.FC<{
  text: string;
  color: string;
  size: number;
  delay: number;
}> = ({ text, color, size, delay }) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const progress = spring({
    frame: frame - delay,
    fps,
    config: { damping: 14, mass: 1.2 },
  });
  
  const y = interpolate(progress, [0, 1], [80 * s, 0]);
  const scale = interpolate(progress, [0, 1], [0.85, 1]);
  const op = interpolate(progress, [0, 0.5], [0, 1], {
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        fontFamily: antonFamily,
        fontSize: size,
        color: color,
        textTransform: "uppercase",
        lineHeight: 0.85,
        transform: `translateY(${y}px) scale(${scale})`,
        opacity: op,
        textShadow: `
          ${4 * s}px ${4 * s}px 0px rgba(0,0,0,0.6),
          ${8 * s}px ${8 * s}px ${15 * s}px rgba(0,0,0,0.5)
        `,
        margin: 0,
        padding: 0,
        textAlign: "center",
        whiteSpace: "nowrap",
      }}
    >
      {text}
    </div>
  );
};

const Bar: React.FC<{
  delay: number;
  width: number;
  height: number;
  color: string;
  direction: number;
  opacity: number;
}> = ({ delay, width, height, color, direction, opacity }) => {
  const frame = useCurrentFrame();
  const { fps, width: canvasW, height: canvasH } = useVideoConfig();
  const s = Math.min(canvasW, canvasH) / 1080;
  
  const progress = spring({
    frame: frame - delay,
    fps,
    config: { damping: 15, mass: 1.2 },
  });

  const startX = direction === 1 ? -width : width;
  const x = interpolate(progress, [0, 1], [startX, 0]);
  const op = interpolate(progress, [0, 0.2], [0, opacity], {
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        width: width,
        height: height,
        backgroundColor: color,
        transform: `translateX(${x}px)`,
        opacity: op,
        boxShadow: `0 0 ${20 * s}px rgba(0,0,0,0.3)`,
      }}
    />
  );
};

const Flare: React.FC<{ accentColor: string }> = ({ accentColor }) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const sweepProgress = spring({
    frame: frame - 20,
    fps,
    config: { damping: 25, mass: 2.5 },
  });
  
  const flareX = interpolate(sweepProgress, [0, 1], [-width, width * 1.5]);
  const op = interpolate(sweepProgress, [0, 0.2, 0.8, 1], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        position: "absolute",
        top: height * 0.68,
        left: flareX,
        width: 500 * s,
        height: 3 * s,
        backgroundColor: "#ffffff",
        boxShadow: `0 0 ${40 * s}px ${15 * s}px ${accentColor}`,
        borderRadius: "50%",
        opacity: op,
        transform: "translateY(-50%)",
        zIndex: 20,
      }}
    />
  );
};

const TitleCard: React.FC<TitleCardProps> = ({
  backgroundColor = "#061A22",
  transparentBackground = false,
  durationInSeconds = 4,
  line1Text = "POP",
  line2Text = "QUIZ",
  line3Text = "MONDAY",
  line1Color = "#FFFFFF",
  line2Color = "#00E5CC",
  line3Color = "#FFFFFF",
  accentColor = "#00E5CC",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Exit transition
  const exitDuration = 15;
  const exitStart = Math.max(0, fps * durationInSeconds - exitDuration);
  const globalOpacity = interpolate(
    frame,
    [exitStart, fps * durationInSeconds - 1],
    [1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Subtle continuous push-in
  const globalScale = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [1, 1.05]
  );

  // Generate particles once
  const particles = useMemo(
    () =>
      Array.from({ length: 40 }).map((_, i) => ({
        x: random(`px-${i}`),
        y: random(`py-${i}`) * 2 - 0.5,
        size: random(`ps-${i}`) * 4 + 2,
        speed: random(`psp-${i}`) * 2 + 1,
        delay: random(`pd-${i}`) * 30,
      })),
    []
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          opacity: globalOpacity,
          transform: `scale(${globalScale})`,
          transformOrigin: "center center",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          overflow: "hidden",
        }}
      >
        {/* Deep background gradient */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            background: `radial-gradient(circle at center, ${accentColor}33 0%, transparent 80%)`,
          }}
        />

        {/* Digital Grid Pattern */}
        <svg
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            opacity: 0.15,
          }}
        >
          <defs>
            <pattern
              id="dotGrid"
              x="0"
              y="0"
              width={24 * s}
              height={24 * s}
              patternUnits="userSpaceOnUse"
            >
              <circle cx={2 * s} cy={2 * s} r={2 * s} fill="#ffffff" />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#dotGrid)" />
        </svg>

        {/* Floating Particles */}
        {particles.map((p, i) => {
          const yPos = p.y * height - (frame - p.delay) * p.speed * s;
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: p.x * width,
                top: yPos,
                width: p.size * s,
                height: p.size * s,
                backgroundColor: "#ffffff",
                borderRadius: "50%",
                opacity: 0.4,
                boxShadow: `0 0 ${p.size * 2 * s}px #ffffff`,
                pointerEvents: "none",
              }}
            />
          );
        })}

        {/* Top-Left Diagonal Bars */}
        <div
          style={{
            position: "absolute",
            top: -height * 0.4,
            left: -width * 0.3,
            width: width * 2,
            height: height * 1.5,
            transform: "rotate(-35deg)",
            display: "flex",
            flexDirection: "column",
            gap: 25 * s,
            pointerEvents: "none",
          }}
        >
          <Bar delay={5} width={width * 2} height={120 * s} color={accentColor} direction={1} opacity={1} />
          <Bar delay={9} width={width * 2} height={20 * s} color="#ffffff" direction={1} opacity={1} />
          <Bar delay={13} width={width * 2} height={60 * s} color={accentColor} direction={1} opacity={0.3} />
        </div>

        {/* Bottom-Right Diagonal Bars */}
        <div
          style={{
            position: "absolute",
            bottom: -height * 0.5,
            right: -width * 0.3,
            width: width * 2,
            height: height * 1.5,
            transform: "rotate(-35deg)",
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-end",
            justifyContent: "flex-end",
            gap: 25 * s,
            pointerEvents: "none",
          }}
        >
          <Bar delay={8} width={width * 2} height={160 * s} color={accentColor} direction={-1} opacity={1} />
          <Bar delay={12} width={width * 2} height={15 * s} color="#ffffff" direction={-1} opacity={1} />
        </div>

        {/* Inner Glowing Depth Behind Text */}
        <div
          style={{
            position: "absolute",
            width: 700 * s,
            height: 700 * s,
            background: `radial-gradient(circle, ${accentColor}66 0%, transparent 60%)`,
            filter: `blur(${70 * s}px)`,
            opacity: 0.6,
          }}
        />

        {/* Main Title Stack */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            transform: "skewX(-10deg)",
            zIndex: 10,
          }}
        >
          <TextLine text={line1Text} color={line1Color} size={220 * s} delay={5} />
          <TextLine text={line2Text} color={line2Color} size={340 * s} delay={10} />
          <TextLine text={line3Text} color={line3Color} size={220 * s} delay={15} />
        </div>

        {/* Lens Flare Sweep */}
        <Flare accentColor={accentColor} />
      </div>
    </AbsoluteFill>
  );
};

export default TitleCard;